  "DL5851": {
    "clinical": {
      "indication": "用于胃食管反流病、幽门螺杆菌根除方案相关消化性溃疡、NSAID相关溃疡的治疗或预防，以及其他经确诊的酸相关疾病。",
      "dosage": "肠溶片整片吞服。成人常用20mg或40mg每日1次；根除幽门螺杆菌须与抗菌药联合，疗程与剂量按具体适应症执行。",
      "adverseReactions": "常见头痛、腹痛、腹泻、便秘、恶心和腹胀；长期或大剂量可见低镁、维生素B12缺乏、骨折、艰难梭菌相关腹泻及肾损害。",
      "precautions": "对本品或其他苯并咪唑类过敏者禁用。警惕报警症状并排除恶性病变；与氯吡格雷合用可降低其抗血小板活性，应避免；长期用药监测镁、肾功能及必要营养指标。"
    },
    "source": {
      "status": "verified-label",
      "label": "医院说明书库：艾司奥美拉唑镁肠溶片",
      "url": "https://swin.zy91.com/pages/m-instruction/m.instruction.html?hospitalCode=1&webHisId=32810",
      "checkedAt": "2026-08-25"
    },
    "origin": "manual-verified"
  },
  "FX6011": {
    "clinical": {
      "indication": "配合饮食和运动，用于适合沙格列汀与二甲双胍联合治疗的成人2型糖尿病患者。",
      "dosage": "通常晚餐时每日1次，整片吞服，不得压碎、切开或咀嚼；剂量根据既往治疗、疗效及耐受性个体化，遵守最大日剂量。",
      "adverseReactions": "常见腹泻、恶心、头痛、上呼吸道感染；可发生低血糖（合用胰岛素/促泌剂时增加）、胰腺炎、严重关节痛、类天疱疮和乳酸性酸中毒。",
      "precautions": "严重肾功能损害和代谢性酸中毒禁用。开始及治疗期间评估肾功能；造影、手术、缺氧、脱水和大量饮酒时评估暂停。心衰高风险患者留意呼吸困难和水肿。"
    },
    "source": {
      "status": "verified-label",
      "label": "正大天晴：沙格列汀二甲双胍缓释片资料",
      "url": "https://www.cttq.com/product/jiangtang-detail-25447.htm",
      "checkedAt": "2026-08-25"
    },
    "origin": "manual-verified"
  },
  "DL0636": {
    "clinical": {
      "indication": "本品为局麻药及抗心律失常药。主要用于浸润麻醉、硬膜外麻醉、表面麻醉（包括在胸腔镜检查或腹腔手术时作黏膜麻醉用）及神经传导阻滞。本品也可用于急性心肌梗死后室性早搏和室性心动过速，亦可用于洋地黄类中毒、心脏外科手术及心导管引起的室性心律失常。本品对室上性心律失常通常无效。",
      "dosage": "1．麻醉用（1）成人常用量：①表面麻醉：2%～4%溶液一次不超过100mg。注射给药时一次量不超过4.5mg/kg（不用肾上腺素）或每7mg/kg（用1：200000浓度的肾上腺素）。②骶管阻滞用于分娩镇痛：用1.0%溶液，以200mg为限。③硬脊膜外阻滞：胸腰段用1.5%～2.0%溶液，250～300mg。④浸润麻醉或静注区域阻滞：用0.25%～0.5%溶液，50～300mg。⑤外周神经阻滞：臂丛(单侧)用1.5%溶液，250～300mg；牙科用2%溶液，20～100mg；肋间神经(每支)用1%溶液，3",
      "adverseReactions": "（1）本品可作用于中枢神经系统，引起嗜睡、感觉异常、肌肉震颤、惊厥昏迷及呼吸抑制等不良反应。（2）可引起低血压及心动过缓。血药浓度过高，可引起心房传导速度减慢、房室传导阻滞以及抑制心肌收缩力和心输出量下降。",
      "precautions": "（1）防止误入血管，注意局麻药中毒症状的诊治。（2）肝肾功能障碍、肝血流量减低、充血性心力衰竭、严重心肌受损、低血容量及休克等患者慎用。（3）对其他局麻药过敏者，可能对本品也过敏，但利多卡因与普鲁卡因胺、奎尼汀间尚无交叉过敏反应的报道。（4）本品严格掌握浓度和用药总量，超量可引起惊厥及心跳骤停。（5）其体内代谢较普鲁卡因慢，有蓄积作用，可引起中毒而发生惊厥。（6）某些疾病如急性心肌梗死病人常伴有α1-酸性蛋白及蛋白率增加，利多卡因蛋白结合也增加而降低了游离血药浓度。（7）用药期间应注意检查血压、监测心电图，并备有抢救设备；心电图P-R间期延长或QRS波增宽，出现其他心律失常或原有心律失常加重者应立即停药。"
    },
    "source": {
      "status": "verified-monograph",
      "label": "药源网：盐酸利多卡因注射液说明书",
      "url": "https://www.yaopinnet.com/huayao/hy24352.htm",
      "checkedAt": "2026-08-25"
    },
    "origin": "yaopinnet-verified"
  },
