      "precautions": "1.避免接触眼睛及黏膜（如口、鼻黏膜）。\n2.用药部位如有烧灼感、瘙痒、红肿等情况应停药，并将局部药物洗净，必要时向医师咨询。\n3.孕妇、哺乳期妇女应在医师指导下使用。\n4.不得用于皮肤破损处及感染性创口，且不宜大面积使用。\n5.对本品过敏者禁用，过敏体质者慎用。\n6.本品性状发生改变时禁止使用。\n7.请将本品放在儿童不能接触的地方。\n8.儿童必须在成人监护下使用。\n9.如正在使用其他药品，使用本品前请咨询医师或药师。"
