      "dosage": "外用。一次10ml，一日1次。将药液浸于敷带上贴敷患处30～60分钟；20天为一疗程。",
      "adverseReactions": "患者局部出现灼热感，连续多次使用时部分患者在用药部位可能会产生皮疹或局部痒感，停止用药后即可消失。每次用药后可涂少量润肤膏，可减轻和防止。",
      "precautions": "1.本品为外用药，禁止内服。\n2.忌食生冷、油腻食物。\n3.切勿接触眼睛、口腔等黏膜处。皮肤破溃处禁用。\n4.经期及哺乳期妇女慎用。儿童、年老体弱者应在医师指导下使用。高血压患者用于颈椎应慎用。\n5.本品不宜长期或大面积使用，用药后皮肤过敏者应停止使用，症状严重者应去医院就诊。\n6.用药后3小时内不得吹风，不接触冷水。\n7.患者可视病症及敷贴浸药液情况调整每次使用量（5毫升～10毫升）。\n8.本品放置后稍有浑浊或沉淀，不影响疗效，摇匀后使用。\n9.用药3天症状无缓解，应去医院就诊。\n10.对本品及酒精过敏者禁用，过敏体质者慎用。\n11.对本品过敏者禁用，过敏体质者慎用。\n12.本品性状发生改变时禁止使用。\n13.儿童必须在成人监护下使用。\n14.请将本品放在儿童不能接触的地方。\n15.如正在使用其他药品，使用本品前请咨询医师或药师。"
