      "precautions": "1对纯合子家族性高胆固醇血症疗效差。\n2治疗期间，应定期检查肝功能，如SGPT和SGOT增高等于或超过正常上限三倍且为持续性时，应停止治疗。\n3有肝脏疾病史或饮酒史的病人应慎用。\n4使用HMG-CoA还原酶抑制剂类降血脂药偶可引导起升高，如升高值为正常上限的10\u0000"
