      "dosage": "口服。\n胃溃疡：一次0.1g，一日三次（分早、晚饭后半小时及睡前服用）。",
      "adverseReactions": "腹胀、便秘等。据资料报道服用瑞巴派特后，可出现口渴、头晕、恶心、呕吐、烧心、暖气、腹痛、腹泻、喉部异物感、肝功能异常、BuN升高、乳房发胀、溢乳、月经率乱及过敏症状（搔痒、皮疹、湿疹）。",
