      "dosage": "口服。一次4片，一日2次。",
      "adverseReactions": "监测数据显示，本品有以下不良反应报告：恶心、呕吐、口干、腹痛、腹胀、腹泻、腹部不适、食欲减退、排便频率增加、皮疹、瘙痒、荨麻疹、头晕、头痛、嗜睡、乏力、胸部不适、心悸、过敏反应等。",
      "precautions": "1.忌食辛辣油腻煎炸食物。\n2.本品含蔗糖，糖尿病患者慎用。\n3.脾胃虚寒者慎用。\n4.不宜在服用本品期间同时服用温补性中药。\n5.有高血压、心脏病、肝病、肾病等患者或在接受其他治疗的患者应在医师指导下服用。\n6.应按照用法用量服用，年老体弱者、大便溏软者应在医师指导下服用。\n7.服药三天后症状无改善，或出现其他症状，应去医院就诊。\n8.过敏体质者慎用。\n9.本品性状发生改变时禁止使用。\n10.请本品放在儿童不能接触的地方。\n11.如正在使用其他药品，使用本品前请咨询医师或药师。"
