      "precautions": "1.伴有其他严重的慢性病，或在治疗期间又患有其他疾病，应去医院就诊，在医师指导下服药。\n2.服药后症状无改善，应去医院就诊。\n3.按照用法用量服用，长期服用，应向医师咨询。\n4.对本品过敏者禁用，过敏体质者慎用。\n5.本品性状发生改变时禁止使用。\n6.儿童必须在成人监护下使用。\n7.请将本品放在儿童不能接触的地方。\n8.如正在使用其他药品，使用本品前请咨询医师或药师。"
