  "DL0732": {
    "clinical": {
      "indication": "1.微血管病的治疗：\n糖尿病性微血管病变---视网膜病及肾小球硬化症(基-威氏综合症)；\n微血管损伤---伴有毛细血管脆性和通透性增加，毛细血管病，手足发绀。\n2.用于慢性静脉功能不全(静脉曲张综合征)及其后遗症(栓塞后综合征，腿部溃疡，紫癜性皮炎等郁积性皮肤病，周围血管郁积性水肿等)的辅助治疗。",
      "dosage": "成人：\n糖尿病性视网膜病变：一次1粒，一日3次(早、中、晚各服一次)。其他适应症：一次1粒，一日2次(早、晚各一次)，如临床症状有所改善，则略去晚上服药一次(大约服药一个月后)。\n口服：\n为减少胃部不适，应随餐或餐后立即服用，不要咀嚼，并配合少量液体服用。\n肾功能损伤患者：\n尚未在肾功能损伤患者中开展本品的安全性及有效性研究。由于本品随尿液排出，在肾功能损伤的情况下应谨慎使用。对于这些患者，特别是严重肾功能损伤需要透析的患者，应减少剂量。\n肝功能损伤患者：\n尚未在肝功能损伤患者中开展本品的安全性及有效性研究，这些患者在用药时应谨慎。",
      "adverseReactions": "本品上市后监测到以下不良反应/事件：\n皮肤及皮下组织：瘙痒、潮红、皮疹(红斑、斑丘疹、水疱等)、荨麻疹；有中毒性表皮坏死松解症、大疱性表皮坏死松解型药疹、急性泛发型发疹性脓疱病、药物超敏反应综合征(DRESS综合征)等严重皮肤反应的个例报道。\n胃肠系统：腹部不适(如腹痛、腹泻、腹胀)、食欲减退、消化不良、胃肠道反应(如恶心、呕吐)。\n全身性疾病及给药部位各种反应：发热、畏寒、水肿、疲劳、乏力。\n血液和淋巴系统：粒细胞减少症、粒细胞缺乏症、白细胞减少症(白细胞计数降低)、中性粒细胞减少症。\n免疫系统：超敏反应、类过敏反应。\n肝胆系统：肝功能异常(如丙氨酸氨基转移酶升高)、肝细胞损伤。\n骨骼和结缔组织：关节痛、肌痛。\n神经系统：头晕、头痛。",
      "precautions": "1.非常罕见的情况下，羟苯磺酸钙可能导致粒细胞缺乏症。在这种情况下，可能出现包括高热、口腔感染(扁桃体炎)、咽喉痛、肛门与生殖器炎症及其他常见感染症状，一旦在治疗中出现这些症状，需立即停药，及时就医并评估血常规。\n2.羟苯磺酸钙可能会诱发重度超敏反应(过敏反应或休克)，如出现红斑、斑丘疹、水疱等皮肤反应，需立即停药，并及时就医。\n3.严重肾功能不全需透析的病人应慎用。\n4.服用羟苯磺酸钙会导致通过氧化酶法检测血肌酐的结果偏低。如果患者服用该药，应告知医生。\n5.羟苯磺酸钙不影响驾驶和操作机器。"
    },
    "source": {
      "status": "verified-monograph",
      "label": "药源网：羟苯磺酸钙胶囊说明书",
      "url": "https://www.yaopinnet.com/huayao/hy20937.htm",
      "checkedAt": "2026-08-25"
    },
    "origin": "yaopinnet-verified"
  },
  "DL0273": {
    "clinical": {
      "indication": "伴随下述疾患的角结膜上皮损伤：\n·干燥综合征(Sjögren's syndrome)、斯·约二氏综合征(Stevens-Johnson syndrome)、干眼综合征(dry eye syndrome)等内因性疾患；\n·手术后、药物性、外伤、配戴隐形眼镜等外因性疾患。",
      "dosage": "一般1次1滴，1日滴眼5～6次，可根据症状适当增减。\n一般使用0.1%浓度的玻璃酸钠滴眼液，重症疾患以及效果不明显时使用0.3%的玻璃酸钠滴眼液。",
      "adverseReactions": "1.过敏症：有时可能会发生眼睑炎、眼睑皮肤炎等，出现上述症状应停药。2.有时可能会出现搔痒感、刺激感、充血、弥漫性表层角膜炎等角膜障碍，出现上述症状时应停药。",
      "precautions": "1.给药途径：只可做滴眼用。\n2.给药时：\n(1)为了防止污染药液,滴眼时应注意避免容器的前端直接接触眼部。\n(2)不要在配戴隐形眼镜时滴眼。\n(3)本品开封后请在28天内使用，过期应丢弃。"
    },
    "source": {
      "status": "verified-monograph",
      "label": "药源网：玻璃酸钠滴眼液说明书",
      "url": "https://www.yaopinnet.com/huayao/hy65732.htm",
      "checkedAt": "2026-08-25"
    },
    "origin": "yaopinnet-verified"
  },
