      "indication": "用于缓解支气管哮喘、慢性支气管炎、肺气肿及其他伴支气管痉挛肺部疾病的症状。",
      "dosage": "经合适雾化器吸入。每次剂量、稀释方式和每日次数按年龄、病情及现行说明书，由医务人员指导；不得口服或注射。",
