      "precautions": "1.忌不易消化食物。\n2.感冒发热病人不宜服用。\n3.有高血压、心脏病、肝病、糖尿病、肾病等慢性病严重者应在医师指导下服用。\n4.儿童、孕妇、哺乳期妇女应在医师指导下服用。\n5.服药4周症状无缓解，应去医院就诊。\n6.对本品过敏者禁用，过敏体质者慎用。\n7.本品性状发生改变时禁止使用。\n8.儿童必须在成人监护下使用。\n9.请将本品放在儿童不能接触的地方。\n10.如正在使用其他药品，使用本品前请咨询医师或药师。"
