  "FX0421": {
    "clinical": {
      "indication": "用于高血压患者的治疗。",
      "dosage": "成年人的初始剂量为每次5mg（每次一片），每天一次，早饭后服用。根据患者的临床反应，可将剂量增加，最大可增至每次10mg（每次二片），每日一次，早饭后服用。",
      "adverseReactions": "泌尿系统：尿频、尿酸、肌酸、尿酸氮上升、尿蛋白阳性、尿沉渣阳性；&#xA;神经系统：头痛、头晕、肩肌肉僵硬、发困、失眠、手颤动、健忘；&#xA;循环系统：面色潮红、心悸、燥热、心电图异常（ST段减低、T波逆转）、低血压、胸痛、畏寒、期外收缩、性功能障碍；&#xA;消化系统：AST、ALT、y-GTP上升等肝功能异常、呕吐、腹痛、口渴、便秘、腹胀；&#xA;血液系统：白细胞数、嗜中性白细胞异常血小板减少、红细胞、红细胞比容、嗜酸性粒细胞和淋巴细胞异常；&#xA;过敏：药疹、瘙痒感；&#xA;其他：浮肿、疲倦、血清胆固醇上升、血清K和P的异常、眼部干燥、充",
      "precautions": "老年患者使用时应从小剂量开始，并仔细观察药物的治疗反应。 &#xA;与地高辛合用时，应密切注意地高辛的毒性反应。 &#xA;肝功能不全患者服用西尼地平时，血浆西尼地平的浓度会增加，故应慎用。 &#xA;西尼地平在肝脏中代谢，故与下列药物合用时应注意： &#xA;- 抑制CYP3A4同工酶的药物，如：西咪替丁、酮康唑、伊曲康唑、红霉素、HIV蛋白酶抑制剂和氟西汀 &#xA;- CYP3A4同工酶诱导剂，如：苯妥英、卡马西平和利福平 &#xA;- 需CYP3A4同工酶代谢的药物，如：环孢菌素 &#xA;- 抑制或诱导CYP2C19同工酶的药物 &#xA;- 需CYP2C1"
    },
    "source": {
      "status": "verified-monograph",
      "label": "39药品通：西尼地平片(西乐)详细说明书",
      "url": "https://ypk.39.net/507296/manual/",
      "checkedAt": "2026-08-25"
    },
    "origin": "39-drug-verified"
  },
