  "DL0796": {
    "clinical": {
      "indication": "氯沙坦钾氢氯噻嗪用于治疗高血压，适用于联合用药治疗的患者。",
      "dosage": "常用的氯沙坦钾氢氯噻嗪起始和维持剂量为每日一次，每次一片氯沙坦钾氢氯噻嗪 50-12.5 （氯沙坦钾 50mg/ 氢氯噻嗪12.5mg）。对氯沙坦钾氢氯噻嗪 50-12.5 反应不足的患者，剂量可增至每日1次，每次2片海捷亚 50-12.5 。最大服用剂量为每日 1 次，每次 2 片海捷亚 50-12.5 。通常在服药后三周内达到抗高血压疗效。",
      "adverseReactions": "在氯沙坦钾 - 氢氯噻嗪的临床试验中，未发现这种复方药物有特殊的不良反应，只限于那些以前报道过的氯沙坦钾和 / 或氢氯噻嗪的不良反应。这种复方制剂不良反应的总体发生率与安慰剂相似，中断治疗的百分率也与安慰剂相似。 一般而言，用氯沙坦钾 - 氢氯噻嗪治疗的耐受性良好，大多数不良反应的性质轻微和短暂，不需中断治疗。 氯沙坦 - 氢氯噻嗪治疗原发性高血压的临床对照试验中，头晕是唯一被报道发生率高于安慰剂 1% 或以上的药物不良反应。 上市后发现的其他不良反应： 过敏：氯沙坦治疗的患者中很少有血管性水肿（包括喉和声门肿导致呼吸道堵塞和 / 或脸、唇、咽和 / 或舌的肿胀）的报道：其中一些患者曾因服用其他药物（如 ACE 抑制剂），而出现过血管性水肿。 &#xE5E5;胃肠道：肝炎（在使用氯沙坦患者中罕见报道）；腹泻。 实验室化验结果：临床对照试验中，标准实验室参数发生临床重要改变者极少与服用氯沙坦钾氢氯噻嗪有关，有 0.7% 患者发生高血钾（血钾 5.5mEq/L ），但无需因此停用氯沙坦钾氢氯噻嗪。血谷丙转氨酶升高很少发生，一般停药即恢复。",
      "precautions": "1 氯沙坦钾氢氯噻嗪不能用于血容量减少的患者（如服用高剂量利尿剂者）。&#xA;2 严重肾功能不全（肌酐清除率&le; 30ml/min ）或肝功能异常的患者，不建议使用氯沙坦钾氢氯噻嗪。&#xA;3 老年患者不需调整起始剂量。&#xA;4 氯沙坦钾氢氯噻嗪可与其他抗高血压药物联合使用。&#xA;5 进食与否，均可服用氯沙坦钾氢氯噻嗪。"
    },
    "source": {
      "status": "verified-monograph",
      "label": "39药品通：氯沙坦钾氢氯噻嗪片(海捷亚)详细说明书",
      "url": "https://ypk.39.net/502052/manual/",
      "checkedAt": "2026-08-25"
    },
    "origin": "39-drug-verified"
  },
  "DL0305": {
    "clinical": {
      "indication": "本品主要用于厌氧菌感染的治疗。",
      "dosage": "静脉滴注。1、成人常用量：静脉给药首次按体重15mg/kg（70kg成人为1g），维持量按体重7.5mg/kg，每6-8小时静脉滴注一次。2、小儿常用量：注射剂量同成人。或遵医嘱。",
      "adverseReactions": "不良反应以消化道反应最为常见，包括恶心、呕吐、食欲不振、腹泻、腹部绞痛，一般不影响治疗；神经系统症状有头痛、眩晕，偶有感觉异常、肢体麻木、共济失调、多发性神经炎等，大剂量可致抽搐。少数病例发生荨麻疹、潮红、瘙痒、膀胱炎、排尿困难、黑尿、口中金属味及白细胞减少等，均属可逆性，停药后自行恢复。",
      "precautions": "1、对诊断的干扰：本品的代谢产物可使尿液呈深红色。\n2、原有肝脏疾患者，剂量应减少。出现运动失调或其它中枢神经系统症状时应停药。重复一个疗程之前，应做白细胞计数。厌氧菌感染合并肾功能衰竭者，给药间隔时间应由8小时延长至12小时。\n3、本品可抑制酒精代谢，用药期间应戒酒，饮酒后可能出腹痛、呕吐、头痛等症状。\n4、使用本品期间，如出现任何不良事件和/或不良反应，请咨询医生。\n5、同时使用其他药品，请告知医生。\n6、请放置于儿童不能够触及的地方。\n7、使用前请仔细检查，如药液浑浊或有异物、瓶身破裂、封口渗漏等，切勿使用。\n8、本品一经使用，即有空气进入，剩余药液切勿贮存后再使用。"
    },
    "source": {
      "status": "verified-monograph",
      "label": "药源网：甲硝唑氯化钠注射液说明书",
      "url": "https://www.yaopinnet.com/huayao/hy4964w.htm",
      "checkedAt": "2026-08-25"
    },
    "origin": "yaopinnet-verified"
  },
