  "DL2871": {
    "clinical": {
      "indication": "用于饮食控制及运动锻炼不能有效控制高血糖的2型糖尿病（非胰岛素依赖性）患者。瑞格列奈片可与二甲双胍合同。与各自单独使用相比，二者合用对控制血糖有协同作用。",
      "dosage": "瑞格列奈片应在主餐前服用（即餐前服用）。在口服瑞格列奈片30分钟内即出现促胰岛素分泌反应。通常在餐前15分钟内服用本药。服药时间也可掌握在餐前0～30分钟内。请遵医嘱服用瑞格列奈片。剂量因人而异，以个人血糖而定。推荐起始剂量为0.5毫克，以后如需要可每周或每两周作调整。接受其他口服降血糖药治疗的病人可直接转用瑞格列奈片治疗。其推荐起始剂量为0.5毫克。最大的推荐单次剂量为4mg，进餐时服用。但最大日剂量不应超过16mg。对于衰弱和营养不良的患者，应谨慎调整剂量。如果与二甲双胍合用，应减少瑞格列奈片的剂量。",
      "adverseReactions": "1．低血糖这些反应通常较轻微，通过给予碳水化合物较易纠正。若较严重，可输入葡萄糖。2．视觉异常已知血糖水平的改变可导致暂时性视觉异常，尤其是在治疗开始时。只有极少数病例报告瑞格列奈片治疗开始时发生上述的视觉异常，但在临床试验中没有因此而停用瑞格列奈片的病例。3．胃肠道临床试验中有报告发生胃肠道反应，如腹痛、腹泻、恶心、呕吐和便秘。同其他口服降血糖药物相比，这些症状出现的频率以及严重程度均无差别。4．肝酶系统个别病例报告用瑞格列奈片治疗期间肝功酶指标升高。多数病例为轻度和暂时性，因酶指标升高而停止治疗的病人极少。5．过敏反应可发生皮肤过敏反应，如瘙痒、发红、荨麻疹。由于化学结构不同，没有理由怀疑可能发生与磺脲类药物之间的交叉过敏反应。",
      "precautions": "1．肾功能不良患者慎用，营养不良患者应调整剂量。2．同其他大多数口服促胰岛素分泌降血糖药物一样，瑞格列奈片也可致低血糖。3．与二甲双胍合用会增加发生低血糖的危险性。如果合并用药后仍发生持续高血糖，则不宜继续用口服降糖药控制血糖，而需改用胰岛素治疗。4．在发生应激反应时，如发热、外伤、感染或手术，可能会出现显著高血糖。5．瑞格列奈片尚未在肝功能不全的患者中进行过研究。也未在18岁以下或75岁以上的患者中进行过研究。故肝功能不全的患者审用。6．患者必须慎用，不进餐不服药，同时避免开车时发生低血糖。"
    },
    "source": {
      "status": "verified-monograph",
      "label": "药源网：瑞格列奈片说明书",
      "url": "https://www.yaopinnet.com/huayao/hy25546.htm",
      "checkedAt": "2026-08-25"
    },
    "origin": "yaopinnet-verified"
  },
  "DL2142": {
    "clinical": {
      "indication": "适用于经饮食控制及体育锻炼2～3个月疗效不满意的轻、中度2型糖尿病患者，这类糖尿病患者的胰岛β细胞需有一定的分泌胰岛素功能，且无急性并发症(如感染、创伤、酮症酸中毒、高渗性昏迷等)，不合并妊娠，无严重的慢性并发症。",
      "dosage": "口服：每日服药1次。开始日服5mg，早餐时服用(也可在其它认为方便的时候服用)。以后根据每周测定血糖值或每二月测得糖化血红蛋白值调整剂量。多数病人每日服10mg即可，部分患者须服15mg，每日最大剂量20mg。",
      "adverseReactions": "本品不良反应较少。1.内分泌、代谢系统：本品属于磺酰脲类药物，此类药的不良反应主要为低血糖。2.消化系统：(1)可出现消化道反应如恶心、呕吐、上腹灼热感、食欲减退、腹泻、口中金属味，一般不严重，且与剂量偏大有关。有时可增进食欲，使体重增加。(2)肝脏损害：黄疸、肝功能异常少见。3.血液系统：血液系统不良反应少见，包括白细胞减少、粒细胞缺乏症、贫血、血小板减少症。4.过敏反应：如皮疹，偶有发生剥脱性皮炎者。",
      "precautions": "1.有消化道狭窄、腹泻者不宜用本品。2.下列情况应慎用：体质虚弱、高热、恶心和呕吐、有肾上腺皮质功能减退或垂体前叶功能减退症者。3.用药期间应定期测血糖、尿糖、尿酮体、尿蛋白和肝、肾功能、血象，并进行眼科检查。4.本品每日只需服药一次，且不需在餐前约半小时服。一般在早餐时服药最为方便。5.本品应整片吞服，不可嚼碎或掰开服用。粪便中可出现药片样物，为正常现象，是包裹片剂的不溶性外壳。"
    },
    "source": {
      "status": "verified-monograph",
      "label": "药源网：格列吡嗪控释片说明书",
      "url": "https://www.yaopinnet.com/huayao/hy25183.htm",
      "checkedAt": "2026-08-25"
    },
    "origin": "yaopinnet-verified"
  },
