  "GZ1650": {
    "clinical": {
      "indication": "化浊降脂，活血化瘀，健脾消食。用于痰阻血瘀所致的高脂血症，症见气短、乏力、头晕、头痛、胸闷、腹胀、食少纳呆；也可用于高脂血症及动脉粥样硬化所致的其他的心脑血管疾病的辅助治疗。",
      "dosage": "口服。一次2粒，一日2次，早晚饭后服用；轻、中度患者一日2粒，晚饭后服用。或遵医嘱。",
      "adverseReactions": "1、一般耐受性良好，大部分副作用轻微而短暂。\n2、本品常见不良反应为肠胃道不适，如胃痛、腹胀、胃部灼热等。\n3、偶可引起血清氨基转移酶和肌酸磷酸激酶可逆性升高。\n4、罕见乏力、口干、头晕、头痛、肌痛、皮疹、胆囊疼痛、浮肿、结膜充血和泌尿道刺激症状。",
      "precautions": "1、用药期间应定期检查血脂、血清氨基转移酶和肌酸磷酸激酶；有肝病史者服用本品尤其要注意肝功能的监测。\n2、在本品治疗过程中，如发生血清氨基转移酶增高达正常高限3倍，或血清肌酸磷酸激酶显著增高时，应停用本品。\n3、不推荐孕妇及乳母使用。\n4、饮食宜清淡。\n5、儿童用药的安全性和有效性尚未确定。"
    },
    "source": {
      "status": "verified-monograph",
      "label": "药源网：血脂康胶囊说明书",
      "url": "https://www.yaopinnet.com/zhongyao/zy12566.htm",
      "checkedAt": "2026-08-25"
    },
    "origin": "yaopinnet-verified"
  },
