  "GX1625": {
    "clinical": {
      "indication": "用于治疗伴有血浆同型半胱氨酸水平升高的原发性高血压。马来酸依那普利降低高血压病人的血压，叶酸可以降低血浆同型半胱氨酸水平。降低血浆同型半胱氨酸水平，是否能预防心脑血管事件的发生尚不明确。",
      "dosage": "根据血压控制情况选择不同规格的马来酸依那普利叶酸片。通常推荐起始剂量为每日5mg//0.4mg，根据患者的反应调整给药剂量，或遵医嘱。肝肾功能异常患者和老年患者酌情减量或遵医嘱",
      "adverseReactions": "临床试验中，服用马来酸依那普利叶酸片所出现的不良反应与单用马来酸依那普利的不良反应相似，主要为咳嗽、头痛、口干、疲劳、上腹不适、恶心、心悸、皮疹等。大多数不良反应轻微而短暂，不需终止治疗。",
      "precautions": "1.叶酸降低同型半胱氨酸的作用受到亚甲基四氢叶酸还原酶（MTHFR)基因C677T多态性的显著影响。纯合突变型（TT基因型）的患者服用马来酸依那普利叶酸片后，效果更好。2.本品可与其他降压药特别是利尿剂合用，降压作用明显增强，但不宜与潴钾利尿剂合用。3.个别病人，尤其是在应用利尿剂或血容量减少者，可能会引起血压过度下降。故首次剂量应从低剂量开始，或遵医嘱。4.定期做白细胞技术和肾功能检测。5.本品性状发生改变时禁止使用。6.请将本品放在儿童不能接触的地方。"
    },
    "source": {
      "status": "verified-monograph",
      "label": "39药品通：马来酸依那普利叶酸片(依叶)详细说明书",
      "url": "https://ypk.39.net/1000008256/manual/",
      "checkedAt": "2026-08-25"
    },
    "origin": "39-drug-verified"
  },
