  "GX2830": {
    "clinical": {
      "indication": "用于2型糖尿病，有血管并发症者尤为适用。",
      "dosage": "遵医嘱：通常开始剂量为每日1～2次，每次80mg，以后根据血糖、尿糖水平调整至一日80～240mg，老年病人酌减。",
      "adverseReactions": "服药期间可引起恶心、呕吐，上腹痛、便秘、腹泻，进餐中服用可减少上述不良反应，其它不良反应为血小板减少，粒性白细胞缺乏，贫血等，偶可发生皮肤过敏。",
      "precautions": "1.服用本品期间，仍需注意饮食控制及体育活动。\n2.2型糖尿病患者在发生感染、外伤、手术等应激情况及酮症酸中毒和非酮症高渗性糖尿病昏迷时，应改用胰岛素治疗。\n3.不适用于1型糖尿病患者。\n4.与抗凝药合用时，应定期检查凝血指标。\n5.本品剂量过大、进食过少或剧烈运动时，应注意防止低血糖反应。\n6.应在医师指导下服用。必须定期检查患者血糖、尿糖。"
    },
    "source": {
      "status": "verified-monograph",
      "label": "药源网：格列齐特片(Ⅱ)说明书",
      "url": "https://www.yaopinnet.com/huayao/hy4286r.htm",
      "checkedAt": "2026-08-25"
    },
    "origin": "yaopinnet-verified"
  },
  "GX2091": {
    "clinical": {
      "indication": "用于慢性胃炎及缓解胃酸过多引起的胃痛、胃灼热感（烧心）和反酸。",
      "dosage": "口服。成人一次2粒，一日4次，前3次于三餐前半小时，第4次于晚餐后2小时服用；或一日2次，早晚各服4粒。",
      "adverseReactions": "服药期间口内可能带有氨味，并可使舌苔及大便呈灰黑色，停药后即自行消失；偶见恶心、便秘。",
      "precautions": "1.本品连续使用不得超过7天，症状未缓解，请咨询医师或药师。\n2.儿童用量请咨询医师或药师。\n3.服用本品期间不得服用其他铋制剂，且不宜大剂量长期服用。\n4.如服用过量或出现严重不良反应，应立即就医。\n5.对本品过敏者禁用，过敏体质者慎用。\n6.本品性状发生改变时禁止使用。\n7.请将本品放在儿童不能接触的地方。\n8.儿童必须在成人监护下使用。\n9.如正在使用其他药品，使用本品前请咨询医师或药师。"
    },
    "source": {
      "status": "verified-monograph",
      "label": "药源网：枸橼酸铋钾胶囊说明书",
      "url": "https://www.yaopinnet.com/huayao/hy11824.htm",
      "checkedAt": "2026-08-25"
    },
    "origin": "yaopinnet-verified"
  },
  "GZ1140": {
    "clinical": {
      "indication": "益气活血，通络止痛。用于冠心病心绞痛属心气虚乏、血瘀络阻证，症见胸部憋闷，刺痛、绞痛，固定不移，心悸自汗，气短乏力，舌质紫暗或有瘀斑，脉细涩或结代。亦用于气虚血瘀络阻型中风病，症见半身不遂或偏身麻木，口舌歪斜，言语不利。",
      "dosage": "口服。一次2～4粒，一日3次。",
      "adverseReactions": "上市后监测数据显示本品可见以下胃肠道不良反应如恶心、呕吐、腹痛、腹胀、腹泻、胃部不适，以及皮疹、瘙痒、头晕等。",
      "precautions": "服药后胃部不适者宜改为饭后服。"
    },
    "source": {
      "status": "verified-monograph",
      "label": "药源网：通心络胶囊说明书",
      "url": "https://www.yaopinnet.com/zhongyao/zy11739.htm",
      "checkedAt": "2026-08-25"
    },
    "origin": "yaopinnet-verified"
  },
  "GZ2361": {
    "clinical": {
      "indication": "用于烂喉丹痧，咽喉肿痛，喉风喉痈，单双乳蛾，小儿热疖，痈疡疔疮，乳痈发背，无名肿毒。",
      "dosage": "口服。一日3次，温开水吞服；一岁每次服1粒，二岁每次服2粒，三岁每次服3～4粒，四岁至八岁每次服5～6粒，九岁至十岁每次服8～9粒，成年每次服10粒。另可外敷在皮肤红肿处，取丸十数粒，用冷开水或米醋少许，盛食匙中化散，敷搽四周，每日数次常保潮润，直至肿退为止。如红肿已将出脓或穿烂，切勿再敷。",
      "adverseReactions": "1.过敏反应：这与用量无关，而且不论内服、外用均可引起，主要表现为药疹，也有出现喉头水肿者，严重者会出现过敏性休克，故有过敏体质者应慎用。&#xA;2.子宫收缩：这是因为六神丸中含有麝香所致，孕妇应禁用。&#xA;3.脱毛：有报道因口服、外敷六神丸还含有雄黄，故不宜与多酶丸及胃蛋白酶合用，否则会使药物降效或失效，更不宜与阿托品等联用，否则会促使雄黄氧化，增加毒性反应。六神丸性香燥，易败胃，故宜饭后服用。凡脾胃不足、身体虚弱者应慎用或禁用。",
      "precautions": "1.过敏体质者慎用。&#xA;2.药品性状发生改变时禁止使用。&#xA;3.儿童应遵医嘱，且必须在成人监护夏使用。&#xA;4.请将此药品放在儿童不能接触的地方。&#xA;5.本品含有麝香，运动员慎用。"
    },
    "source": {
      "status": "verified-monograph",
      "label": "39药品通：六神丸(雷氏)详细说明书",
      "url": "https://ypk.39.net/693013/manual/",
      "checkedAt": "2026-08-25"
    },
    "origin": "39-drug-verified"
  },
  "GZ0431": {
    "clinical": {
      "indication": "清热化痰，宣肺止咳。用于外感风热所致的咳嗽，症见发热、恶寒、胸膈满闷、咳嗽咽痛；急性支气管炎、慢性支气管炎急性发作见上述证候者。",
      "dosage": "口服。一次20～30ml，一日3～4次；儿童周岁以内一次5ml，一至三岁一次7ml，三至七岁一次10ml，七岁以上一次15ml，一日3～4次。",
      "adverseReactions": "尚不明确。",
      "precautions": "1.忌烟、酒及辛辣、生冷、油腻食物。\n2.不宜在服药期间同时服用滋补性中药。\n3.支气管扩张、肺脓疡、肺心病、肺结核患者出现咳嗽时应去医院就诊。\n4.高血压、心脏病患者慎用。糖尿病患者及有肝病、肾病等慢性病严重者应在医师指导下服用。\n5.儿童、孕妇、哺乳期妇女、年老体弱者应在医师指导下服用。\n6.服药期间，若患者发热体温超过38.5℃，或出现喘促气急者，或咳嗽加重、痰量明显增多者应去医院就诊。\n7.服药3天症状无缓解，应去医院就诊。\n8.对本品过敏者禁用，过敏体质者慎用。\n9.本品性状发生改变时禁止使用。\n10.儿童必须在成人监护下使用。\n11.请将本品放在儿童不能接触的地方。\n12.如正在使用其他药品，使用本品前请咨询医师或药师。"
    },
    "source": {
      "status": "verified-monograph",
      "label": "药源网：急支糖浆说明书",
      "url": "https://www.yaopinnet.com/zhongyao/zy3821k.htm",
      "checkedAt": "2026-08-25"
    },
    "origin": "yaopinnet-verified"
  },
