      "precautions": "1.必须按推荐剂量服用，不可超量服用。\n2.儿童用量请咨询医师或药师。\n3.孕妇及哺乳期妇女应在医师指导下使用。\n4.如服用过量或出现严重不良反应，应立即就医。\n5.对本品过敏者禁用，过敏体质者慎用。\n6.本品性状发生改变时禁止使用。\n7.请将本品放在儿童不能接触的地方。\n8.儿童必须在成人监护下使用。\n9.如正在使用其他药品，使用本品前请咨询医师或药师。"
