      "dosage": "口服或舌下含服，一次10粒，一日三次，疗程28天或遵医嘱。",
      "adverseReactions": "上市后不良反应监测数据显示复方丹参丸等制剂可见以下不良反应：\n胃肠系统：恶心、呕吐、腹胀、腹痛、腹泻、腹部不适等。\n皮肤及其附件：皮疹、瘙痒等。\n神经系统：头晕、头痛等。\n心血管系统：心悸、胸闷等。\n其他：乏力、口干、过敏或过敏样反应等。",
