  "SX0784": {
    "clinical": {
      "indication": "本品适用于治疗原发性高血压。",
      "dosage": "对大多数病人，通常起始和维持剂量为每天一次50mg。治疗3至6周可达到最大降压效果。在部分病人中，剂量增加到每天一次100mg可产生进一步的降压作用。对血管容量不足的病人(例如应用大剂量利尿剂治疗的病人)，可考虑采用每天一次25mg的起始剂量(见注意事项)。对老年病人或肾损害病人包括做血液透析的病人，不必调整起始剂量。对有肝功能损害病史的的病人应考虑使用较低剂量(见注意事项)。本品可同其他抗高血压药物一起使用。本品可与或不与食物同时服用。",
      "adverseReactions": "本品耐受性良好；不良反应轻微且短暂，尚未发生因药物不良反应而需终止治疗病例。应用本品时总的不良反应发生率与安慰剂类似。在对原发性高血压的临床对照研究中，1%及以上用本品治疗的病人中，与药物有关、发生率比安慰剂高的唯一不良反应是头晕。另外，不足1%的病人发生与剂量有关的体位性低血压。尽管皮疹在对照临床试验中的发生率较安慰剂低，但也有个别报道。在这些原发性高血压的临床双盲对照研究中，应用本品后，不论是否与药物有关，发生率在1%及以上的不良反应有：氯沙坦钾片(n=2085)空白片(n=535)全身腹痛1.71.7乏力/疲劳3.83.9胸痛1.12.6水肿/肿胀1.71.9心血管系统心悸1.00.4心动过速1.01.7消化系统腹泻1.91.9消化不良1.11.5恶心1.82.8肌肉骨胳系统背痛1.61.1肌肉痉挛1.01.1神经/精神系统头晕4.12.4头痛14.117.2失眠1.10.7呼吸系统咳嗽3.12.6鼻充血1.31.1咽炎1.52.6窦性失调1.01.3上呼吸道感染6.55.6本品上市后已报告的其它不良反应包括：过敏反应：血管性水肿(包括导致气道阻塞的喉及声门肿胀，及/或面、唇、咽和/或舌肿胀)在极少数服用氯沙坦治疗的病人中有报道。其中部分病人以前曾因服用包括ACE抑制剂在内的其他药物而发生过血管性水肿。脉管炎，包括亨诺克?舍恩莱因(亨-舍二氏)紫癜已有极少报道。胃肠道反应：肝炎(少有报道)，肝功能异常。血液系统：贫血。肌肉骨胳系统：肌痛。神经/精神系统：偏头痛。呼吸系统：咳嗽。皮肤：荨麻疹，瘙痒。实验室检查结果在原发性高血压临床对照试验中,很少有应用本品的病人在实验室参数方面出现临床上有重要意义的变化。1.5%的病人出现高血钾症(血清钾5.5mEq/L)。ALT的升高较罕见，并在停药后恢复正常。",
      "precautions": "低血压及电解质/体液平衡失调血管容量不足的病人(例如应用大剂量利尿药治疗的病人)，可发生症状性低血压。在使用本品治疗前应该纠正这些情况，或使用较低的起始剂量。(见用法用量)。肝功能损害药代动力学资料表明，肝硬化病人氯沙坦的血浆浓度明显增加，故对有肝功能损害病史的病人应该考虑使用较低剂量(见用法用量)。肾功能损害由于抑制了肾素?血管紧张素系统，已有关于敏感个体出现包括肾衰在内的肾功能的变化的报导；停止治疗后，这些肾功能的变化可以恢复。对于双侧肾动脉狭窄或只有单侧肾脏而肾动脉狭窄的病人，影响肾素?血管紧张素系统的其他药物可增加其血尿素和血清肌酐含量。使用本品也有类似的报导。停止治疗后，这些肾功能的变化可以恢复。"
    },
    "source": {
      "status": "verified-monograph",
      "label": "药源网：氯沙坦钾片说明书",
      "url": "https://www.yaopinnet.com/huayao/hy2714z.htm",
      "checkedAt": "2026-08-25"
    },
    "origin": "yaopinnet-verified"
  },
  "GX3619": {
    "clinical": {
      "indication": "各种原因所致的失水，包括低渗性、等渗性和高渗性失水；高渗性非酮症糖尿病昏迷，应用等渗或低渗氯化钠可纠正失水和高渗状态；低氯性代谢性碱中毒；外用生理盐水冲洗眼部、洗涤伤口等；还用于产科的水囊引产。",
      "dosage": "1．高渗性失水高渗性失水时患者脑细胞和脑脊液渗透浓度升高，若治疗使血浆和细胞外液钠浓度和渗透浓度过快下降，可致脑水肿。故一般认为，在治疗开始的48小时内，血浆钠浓度每小时下降不超过0.5mmol/L。若患者存在休克，应先予氯化钠注射液，并酌情补充胶体，待休克纠正，血钠>155mmol/L，血浆渗透浓度>350mOsm/L，可予0.6%低渗氯化钠注射液。待血浆渗透浓度<330mOsm/L，改用0.9%氯化钠注射液。补液总量根据下列公式计算，作为参考：[血钠浓度(mmol/L)-142]所需",
      "adverseReactions": "（1）输液过多、过快，可致水钠潴留，引起水肿、血压升高、心率加快、胸闷、呼吸困难，甚至急性左心衰竭。（2）过多、过快给予低渗氯化钠可致溶血、脑水肿等。",
      "precautions": "（1）下列情况慎用：①水肿性疾病，如肾病综合征、肝硬化、腹水、充血性心力衰竭、急性左心衰竭、脑水肿及特发性水肿等；②急性肾功能衰竭少尿期，慢性肾功能衰竭尿量减少而对利尿药反应不佳者；③高血压；④低钾血症。（2）根据临床需要，检查血清中钠、钾、氯离子浓度；血液中酸碱浓度平衡指标、肾功能及血压和心肺功能。"
    },
    "source": {
      "status": "verified-monograph",
      "label": "药源网：氯化钠注射液说明书",
      "url": "https://www.yaopinnet.com/huayao/hy2445i.htm",
      "checkedAt": "2026-08-25"
    },
    "origin": "yaopinnet-verified"
  },
