      "indication": "用于治疗葡萄膜炎、角膜炎、巩膜炎，抑制角膜新生血管的形成，治疗眼内手术后、激光滤帘成形术后或各种眼部损伤的炎症反应，抑制白内障手术中缩瞳反应；用于准分子激光角膜切削术后止痛及消炎；春季结膜炎、季节过敏性结膜炎等过敏性眼病，预防和治疗白内障及人工晶体术后炎症及黄斑囊样水肿，以及青光眼滤过术后促进滤过泡形成等。",
      "dosage": "一日4～6次，一次1滴；眼科手术用药：术前3、2、1和0.5小时各滴眼一次，一次1滴。白内障术后24小时开始用药，一日4次，持续用药二周；角膜屈光术后15分钟即可用药，一日4次，持续用药三天。",
      "adverseReactions": "滴眼有短暂烧灼、刺痛、流泪等，极少数可有结膜充血、视物模糊。不足3%患者可出现乏力、困倦、恶心等全身反应。",
