  "SX1794": {
    "clinical": {
      "indication": "用于预防和治疗维生素A及D的缺乏症。如佝偻并夜盲症及小儿手足抽搐症。",
      "dosage": "口服。将软囊滴嘴开口后，内容物滴入婴儿口中（开口方法：建议采用将滴嘴在开水中浸泡30秒，使胶皮融化）。也可直接嚼服胶丸。1岁以上小儿，一次1粒，一日1次。",
      "adverseReactions": "长期过量服用，可产生慢性中毒。早期表现为骨关节疼痛、肿胀、皮肤瘙痒、口唇干裂、发热、头痛、呕吐、便秘、腹泻、恶心等。",
      "precautions": "1.必须按推荐剂量服用，不可超量服用。\n2.高钙血症孕妇可伴有维生素D敏感，功能上又能抑制甲状旁腺活动，以致婴儿有特殊面容、智力低下及患遗传性主动脉弓缩窄。\n3.婴儿对维生素D敏感性个体差异大，有些婴儿对小剂量维生素D很敏感。\n4.老年人长期服用本品，可能因视黄醛清除延迟而至维生素A过量。\n5.如服用过量或出现严重不良反应，应立即就医。\n6.对本品过敏者禁用，过敏体质者慎用。\n7.本品性状发生改变时禁止使用。\n8.请将本品放在儿童不能接触的地方。\n9.儿童必须在成人监护下使用。\n10.如正在使用其他药品，使用本品前请咨询医师或药师。"
    },
    "source": {
      "status": "verified-monograph",
      "label": "药源网：维生素AD滴剂（胶囊型）说明书",
      "url": "https://www.yaopinnet.com/huayao/hy47726.htm",
      "checkedAt": "2026-08-25"
    },
    "origin": "yaopinnet-verified"
  },
  "SX1854": {
    "clinical": {
      "indication": "用于妊娠和哺乳期妇女、更年期妇女、老年人等的钙补充剂，并帮助防治骨质疏松症。",
      "dosage": "口服。一次1片，一日1-2次。",
      "adverseReactions": "嗳气、便秘、腹胀、腹痛、腹泻、胃肠胀气、恶心和呕吐等胃肠不适。过量服用可发生高钙血症，偶可发生奶-碱综合征，表现为高血钙、碱中毒及肾功能不全（因服用牛奶及碳酸钙或单用碳酸钙引起）。",
      "precautions": "1.心肾功能不全者慎用。2. 如服用过量或出现严重不良反应，应立即就医。3. 对本品过敏者禁用，过敏体质者慎用。4. 本品性状发生改变时禁止使用。5. 请将本品放在儿童不能接触的地方。6. 如正在使用其他药品，使用本品前请咨询医师或药师。7. 肾结石患者应在医师指导下使用。"
    },
    "source": {
      "status": "verified-monograph",
      "label": "39药品通：碳酸钙D3片(钙尔奇)详细说明书",
      "url": "https://ypk.39.net/630305/manual/",
      "checkedAt": "2026-08-25"
    },
    "origin": "39-drug-verified"
  },
  "FX2021": {
    "clinical": {
      "indication": "自然绝经和手术绝经所引起的更年期综合症，如潮热、出汗等。",
      "dosage": "本品应整片吞服不可咬嚼，最好能固定每天在同一时间服用。剂量为每天一片（2.5mg），一般在几周内症状即可改善，但至少连续服用三个月方能可获得最佳效果。按此推荐剂量，在医生指导下可连续长期服用。",
      "adverseReactions": "偶见阴道出血或点滴出血，主要出现在服药的第一个月。其他已观察到的副反应包括：头痛和偏头痛，水肿，眩晕，瘙痒，体重增加，恶心，腹痛，皮疹和抑郁，皮脂分泌过多，面部毛发生长增加，肝功能指标变化。",
      "precautions": "1．本品不可作为避孕药使用。\n2．妇女绝经前并有正常周期者如服用本品，其正常周期可能被干扰，因为本品具有抑制排卵的作用，故建议用于绝经一年以后的妇女。\n3. 如不规则阴道出血发生在用药一个月后或用药期间，应找医生检查。\n4. 如已用其他激素替代疗法而要改服本品时，宜先用孕激素撤退出血后再开始服用，以免因子宫内膜已增厚而引起出血。\n5. 长期服用具有激素活性甾体化合物，应定期进行体检。\n6. 少数病人在服药期间可出现阴道出血，如超过推荐剂量引起阴道出血的比例更高，当服用高于推荐剂量时，应定期加服孕激素。\n7. 如出现静脉栓塞征候、肝功能异常，胆道阻塞性黄疸则应立即停药。\n8. 病人如有下述情况应严密观察：\n①肾病、癫痫或偏头痛、三叉神经痛及有上述疾病史者。因本品偶尔可引起液体潴留。\n②高脂血症，尤其是低密度脂蛋白增高者，因在服用本品者中曾发现血脂变化。\n③糖代谢异常者。本品可减低糖耐量，因此需要增加胰岛素或其他降糖药的用量。\n9. 服用本品期间，病人对抗凝剂的敏感性增强，因为血中纤溶活性增强（纤维蛋白原水平降低；抗凝血酶Ⅲ，纤维蛋白溶酶原和纤维蛋白溶解活性值升高），故本品有增强抗凝剂的作用。\n10.应定期检查乳房、子宫内膜增生情况和可能出现的男性化体征。"
    },
    "source": {
      "status": "verified-monograph",
      "label": "药源网：替勃龙片说明书",
      "url": "https://www.yaopinnet.com/huayao/hy65431.htm",
      "checkedAt": "2026-08-25"
    },
    "origin": "yaopinnet-verified"
  },
  "GX4131": {
    "clinical": {
      "indication": "用于念珠菌性外阴阴道病。",
      "dosage": "阴道给药。睡前1片，1片即为一疗程。将药片置于阴道深处。一般用药1次即可，必要时可在4天后进行第二次治疗。",
      "adverseReactions": "偶见局部刺激，如瘙痒或烧灼感。",
      "precautions": "1.孕妇、哺乳期妇女及无性生活史的女性应在医师指导下使用。\n2.使用本品时应避开月经期。\n3.用药部位如有烧灼感、红肿等情况应停药，并将局部药物洗净，必要时向医师咨询。\n4.用药期间注意个人卫生，防止重复感染，使用避孕套或避免房事。\n5.给药时应洗净双手或戴指套或手套。\n6.本品仅供阴道治疗，切忌口服。\n7.对本品过敏者禁用，过敏体质者慎用。\n8.本品性状发生改变时禁止使用。\n9.请将本品放在儿童不能接触的地方。\n10.儿童必须在成人监护下使用。\n11.如正在使用其他药品，使用本品前请咨询医师或药师。"
    },
    "source": {
      "status": "verified-monograph",
      "label": "药源网：克霉唑阴道片说明书",
      "url": "https://www.yaopinnet.com/huayao/hy2826x.htm",
      "checkedAt": "2026-08-25"
    },
    "origin": "yaopinnet-verified"
  },
